```java
public final class Dinheiro {
    private final long centavos;
    private final String moeda;

    public Dinheiro(long centavos, String moeda) {
        if (moeda == null || moeda.isBlank()) throw new IllegalArgumentException("Moeda invalida.");
        this.centavos = centavos;
        this.moeda = moeda;
    }

    public long getCentavos() { return centavos; }
    public String getMoeda() { return moeda; }

    public Dinheiro somar(Dinheiro outro) {
        if (!this.moeda.equals(outro.moeda)) {
            throw new IllegalArgumentException("Moedas incompativeis.");
        }
        return new Dinheiro(this.centavos + outro.centavos, this.moeda);
    }
}
```

